<script setup lang="ts">
import {computed,ref,watch} from 'vue'
import {useRoute,useRouter,onBeforeRouteLeave} from 'vue-router'
import axios from 'axios'
import ReadReference from '../master/ReadReference.vue'
import {api,errorMessage} from '../../api/http'
import {useAuthStore} from '../../stores/auth'
import {runtimeApi,runtimeHeaders,runtimePayload,runtimeKey,runtimeStates,type FormRuntime,type RuntimeValue,type RuntimeField,type ReviewRule,type ValueRevision} from '../../api/ebrRuntime'
const route=useRoute(),router=useRouter(),auth=useAuthStore(),record=ref<FormRuntime|null>(null),fields=ref<RuntimeField[]>([]),values=ref<Record<string,RuntimeValue>>({}),sources=ref<Record<string,string>>({}),busy=ref(false),error=ref(''),conflict=ref(false),reason=ref(''),password=ref(''),comment=ref(''),decision=ref<'PASS'|'REJECT'>('PASS'),reviewRule=ref(''),meaning=ref<'VERIFY'|'APPROVE'>('VERIFY'),signatureMode=ref<'REVIEW'|'SIGN'|null>(null),correction=ref<ValueRevision|null>(null),newValue=ref<RuntimeValue>(null),requests=runtimeHeaders()
let baseline=''
const pendingReviews=computed(()=>record.value?.reviewRequirements.filter(r=>!record.value?.reviews.some(v=>v.formRevision===record.value?.formRevision&&v.reviewRuleId===r.reviewRuleId))??[])
const dirty=computed(()=>JSON.stringify({values:values.value,sources:sources.value})!==baseline),selectedRule=computed(()=>record.value?.reviewRequirements.find(r=>r.reviewRuleId===reviewRule.value)),groups=computed(()=>[...new Set(fields.value.map(f=>/^(.+)\[[0-9]+\]$/.exec(f.occurrencePath)?.[1]).filter((x):x is string=>!!x))]),correctionField=computed(()=>record.value?.definition.fields.find(f=>f.fieldCode===correction.value?.fieldCode))
function sync(data:FormRuntime){record.value=data;fields.value=data.fields.map(f=>({...f}));values.value=Object.fromEntries(data.fields.map(f=>[runtimeKey(f),f.value]));sources.value=Object.fromEntries(data.fields.map(f=>[runtimeKey(f),data.currentValues.find(v=>runtimeKey(v)===runtimeKey(f))?.sourceRef??'']));baseline=JSON.stringify({values:values.value,sources:sources.value})}
function fail(e:unknown){error.value=e instanceof Error&&!axios.isAxiosError(e)?e.message:errorMessage(e);conflict.value=axios.isAxiosError(e)&&e.response?.status===409}
async function load(){busy.value=true;error.value='';try{sync(await runtimeApi.get(String(route.params.formId)));conflict.value=false;reason.value=''}catch(e){fail(e)}finally{busy.value=false}}
function reload(){if((dirty.value||reason.value)&&!window.confirm('重新加载将放弃未保存内容，是否继续？'))return;void load()}
function definition(code:string){return record.value?.definition.fields.find(f=>f.fieldCode===code)}
function input(f:RuntimeField,event:Event){const text=(event.target as HTMLInputElement).value;values.value[runtimeKey(f)]=text===''?null:text}
function multiselect(f:RuntimeField,event:Event){values.value[runtimeKey(f)]=Array.from((event.target as HTMLSelectElement).selectedOptions).map(o=>o.value)}
function addOccurrence(group:string){const members=fields.value.filter(f=>f.occurrencePath.startsWith(`${group}[`));const next=Math.max(...members.map(f=>Number(/\[([0-9]+)\]$/.exec(f.occurrencePath)?.[1]??0)))+1;const codes=new Set<string>();for(const f of members){if(codes.has(f.fieldCode))continue;codes.add(f.fieldCode);const nextField={...f,occurrencePath:`${group}[${next}]`,value:null,displayValue:'',provenance:[]};fields.value.push(nextField);values.value[runtimeKey(nextField)]=null;sources.value[runtimeKey(nextField)]=''}}
async function command(action:'save'|'submit'){if(!record.value)return;busy.value=true;error.value='';try{if(!reason.value.trim())throw Error('请填写操作原因');if(action==='submit'&&dirty.value)throw Error('请先保存当前填写内容');const current=record.value,url=`/forms/${current.id}/${action==='save'?'draft-values':'submit'}`,body={formRevision:current.formRevision,reason:reason.value.trim(),...(action==='save'?{values:runtimePayload(fields.value,values.value,sources.value)}:{})};sync(await api<FormRuntime>({url,method:action==='save'?'PUT':'POST',data:body,headers:requests.forRequest(url,body,current.formRevision)}));requests.complete();reason.value='';conflict.value=false}catch(e){fail(e)}finally{busy.value=false}}
function openReview(rule:ReviewRule){if(dirty.value){error.value='请先保存填写内容';return}reviewRule.value=rule.reviewRuleId;decision.value='PASS';comment.value='';password.value='';signatureMode.value='REVIEW'}
function openSign(m:string){if(m!=='VERIFY'&&m!=='APPROVE')return;meaning.value=m;password.value='';signatureMode.value='SIGN'}
async function sign(){if(!record.value)return;busy.value=true;error.value='';try{if(!password.value||!reason.value.trim())throw Error('请填写操作原因与再认证密码');if(dirty.value)throw Error('请先保存填写内容');const r=record.value,isReview=signatureMode.value==='REVIEW',rule=selectedRule.value;if(isReview&&!rule)throw Error('请选择实际复核规则');const m=isReview?rule!.reviewType:meaning.value,type=isReview?'EBR_REVIEW_RECORD':'EBR_FORM_INSTANCE',id=isReview?`${r.id}:${r.formRevision}:${rule!.reviewRuleId}`:r.id,url=isReview?`/forms/${r.id}/reviews`:`/records/${type}/${id}/sign`;const body:Record<string,unknown>=isReview?{formRevision:r.formRevision,reviewRuleId:rule!.reviewRuleId,decision:decision.value,comment:comment.value||null,reason:reason.value.trim()}:{meaning:m};const headers=requests.forRequest(url,body,r.formRevision);const reauth=await api<{reauthToken:string}>({url:'/auth/reauth',method:'POST',data:{objectType:type,objectId:id,meaning:m,recordVersion:r.formRevision,credential:password.value}});body.reauthToken=reauth.reauthToken;const result=await api<FormRuntime>({url,method:'POST',data:body,headers});if(isReview)sync(result);else sync(await runtimeApi.get(r.id));requests.complete();signatureMode.value=null;reason.value=''}catch(e){fail(e)}finally{password.value='';busy.value=false}}
function openCorrection(field:RuntimeField){const current=record.value?.currentValues.find(v=>runtimeKey(v)===runtimeKey(field));if(!current)return;correction.value=current;newValue.value=field.value}
async function correct(){if(!record.value||!correction.value)return;busy.value=true;error.value='';try{if(!reason.value.trim())throw Error('请填写更正原因');const url=`/field-values/${correction.value.id}/corrections`,body={formRevision:record.value.formRevision,reason:reason.value.trim(),newValue:newValue.value};sync(await api<FormRuntime>({url,method:'POST',data:body,headers:requests.forRequest(url,body,record.value.formRevision)}));requests.complete();correction.value=null;reason.value=''}catch(e){fail(e)}finally{busy.value=false}}
function viewValue(raw:string){try{const v=JSON.parse(raw);return v===null?'未填写':Array.isArray(v)?v.join('、'):String(v)}catch{return raw}}
onBeforeRouteLeave(()=>!dirty.value||window.confirm('离开将放弃未保存内容，是否继续？'))
watch(()=>route.params.formId,load,{immediate:true})
</script>
<template><main data-ui-template="T5" class="admin-page master-page"><header class="admin-page-header"><div><a-button type="link" @click="router.push(`/mes/execution/${route.params.id}`)">← 返回执行工作台</a-button><h1>{{record?.formName??'电子批记录'}}</h1><p v-if="record">{{record.formCode}} · {{runtimeStates[record.status]}} · 内容修订 {{record.formRevision}}</p></div><a-button :disabled="busy" @click="reload">重新加载</a-button></header><a-alert v-if="error" type="error" :message="error" show-icon/><a-alert v-if="conflict" type="warning" message="内容已变化，当前输入已保留。请核对后重新加载。" show-icon/>
<template v-if="record"><details class="runtime-evidence"><summary>冻结版本与提交信息</summary><a-card title="冻结版本与提交信息" class="form-section"><div class="master-form"><label><span class="form-field-label">表单实例</span><span>{{record.id}} · 第 {{record.occurrenceNo}} 份</span></label><label><span class="form-field-label">提交人 / 时间</span><span>{{record.submittedBy??'—'}} / {{record.submittedAt??'—'}}</span></label><label class="form-full-row"><span class="form-field-label">定义摘要</span><span class="digest">{{record.definitionHash}}</span></label></div></a-card>
</details>
<a-card title="现场记录" class="form-section"><div class="runtime-grid"><template v-for="field in fields" :key="runtimeKey(field)"><div v-if="field.visible" class="runtime-field"><label :for="runtimeKey(field)" class="form-field-label">{{field.label}}<span v-if="field.required" class="required"> *</span><small v-if="field.occurrencePath">{{field.occurrencePath}}</small></label><div class="runtime-control"><span v-if="field.readonly" class="master-read-value">{{field.displayValue||'—'}}</span><select v-else-if="field.type==='BOOLEAN'" :id="runtimeKey(field)" class="master-native-input" :value="values[runtimeKey(field)]===null?'':String(values[runtimeKey(field)])" :disabled="busy" @change="values[runtimeKey(field)]=($event.target as HTMLSelectElement).value===''?null:($event.target as HTMLSelectElement).value==='true'"><option value="">未填写</option><option value="true">是</option><option value="false">否</option></select><select v-else-if="['ENUM','MULTI_ENUM'].includes(field.type)" :id="runtimeKey(field)" class="master-native-input" :multiple="field.type==='MULTI_ENUM'" :value="values[runtimeKey(field)]??''" :disabled="busy" @change="field.type==='MULTI_ENUM'?multiselect(field,$event):input(field,$event)"><option v-if="field.type==='ENUM'" value="">请选择</option><option v-for="option in definition(field.fieldCode)?.options.filter(o=>o.activeFlag)" :key="option.optionCode" :value="option.optionValue">{{option.optionLabel}}</option></select><textarea v-else-if="field.type==='TEXTAREA'" :id="runtimeKey(field)" :value="String(values[runtimeKey(field)]??'')" class="master-native-input" :disabled="busy" maxlength="4000" @input="input(field,$event)"/><input v-else :id="runtimeKey(field)" :type="field.type==='DATE'?'date':field.type==='TIME'?'time':'text'" :inputmode="['NUMBER','TIMER'].includes(field.type)?'decimal':'text'" :value="String(values[runtimeKey(field)]??'')" :placeholder="definition(field.fieldCode)?.placeholder??(field.type==='DATETIME'?'UTC 时间，例如 2026-10-03T08:00:00Z':'')" class="master-native-input" :disabled="busy" maxlength="4000" @input="input(field,$event)"/><span v-if="field.unitId" class="muted"><ReadReference field="unitId" :value="field.unitId"/></span><a-tag v-if="field.validationState!=='VALID'" :color="field.validationState==='BLOCK'?'red':'orange'">{{({MISSING:'未填写',BLOCK:'规则阻断',WARN:'规则警告'} as Record<string,string>)[field.validationState]}}</a-tag><details class="runtime-provenance"><summary>来源 {{({MANUAL:'手工记录',INSTRUMENT:'仪器采集',BARCODE:'扫码记录',CALCULATED:'计算结果'} as Record<string,string>)[field.source]??field.source}}</summary><small>证据 {{field.provenance.join('、')||'—'}}</small></details><label v-if="field.source==='BARCODE'&&!field.readonly" class="barcode-source"><span>扫码来源</span><input v-model="sources[runtimeKey(field)]" class="master-native-input" :aria-label="`${field.label}扫码来源`" maxlength="128" :disabled="busy"/></label><a-button v-if="field.allowedActions.includes('CORRECT')" size="small" :disabled="busy||dirty" @click="openCorrection(field)">受控更正</a-button></div></div></template></div><a-space v-if="record.allowedActions.includes('SAVE')" wrap><a-button v-for="group in groups" :key="group" :disabled="busy" @click="addOccurrence(group)">新增 {{group}} 记录行</a-button></a-space><p v-if="dirty" class="muted">有未保存的现场记录。</p></a-card>
<a-card v-if="record.allowedActions.length" title="受控操作" class="form-section"><label class="form-inline-row"><span class="form-field-label">操作原因</span><textarea v-model="reason" class="master-native-input" aria-label="操作原因" maxlength="1000" :disabled="busy"/></label><a-space wrap><a-button v-if="record.allowedActions.includes('SAVE')" type="primary" :disabled="busy||conflict" @click="command('save')">保存草稿</a-button><a-button v-if="record.allowedActions.includes('SUBMIT')" :disabled="busy||dirty||conflict" @click="command('submit')">提交记录</a-button><a-button v-for="rule in (record.allowedActions.includes('REVIEW')?pendingReviews:[])" :key="rule.reviewRuleId" :disabled="busy||dirty||conflict||!auth.can(rule.reviewType==='VERIFY'?'ebr:review:verify':'ebr:review:approve')||!auth.can('ebr:sign')" @click="openReview(rule)">{{rule.reviewType==='VERIFY'?'核对':'批准'}} · {{rule.requiredRole}} · {{rule.objectCode}}</a-button></a-space></a-card>
<a-card v-if="record.signatureRequirements.length" title="所需电子签名" class="form-section"><div v-for="(rule,i) in record.signatureRequirements" :key="i" class="signature-row"><span>{{rule.objectScope}} / {{rule.objectCode}} · {{rule.meaning}} · {{rule.requiredRole}} · 顺序 {{rule.sequenceNo}}</span><a-button :disabled="busy||dirty||record.status==='DRAFT'||!auth.can('ebr:sign')" @click="openSign(rule.meaning)">签署</a-button></div><p>有效签名：{{record.signatureIds.join('、')||'—'}}</p></a-card>
<details class="runtime-evidence"><summary>更多记录与审计证据</summary><a-card title="规则执行证据" class="form-section"><div class="history-scroll"><table class="runtime-table"><thead><tr><th>规则</th><th>触发点</th><th>结果</th><th>输出</th><th>时间</th></tr></thead><tbody><tr v-for="rule in record.ruleExecutions" :key="rule.id"><td>{{rule.ruleCode}}</td><td>{{rule.triggerPoint}}</td><td>{{rule.passed?'通过':rule.severity==='WARN'?'警告':'阻断'}}</td><td>{{rule.outputJson??'—'}}</td><td>{{rule.executedAt}}</td></tr></tbody></table><a-empty v-if="!record.ruleExecutions.length" description="尚无规则执行证据"/></div></a-card>
<a-card title="字段修订历史" class="form-section"><div class="history-scroll"><table class="runtime-table"><thead><tr><th>字段 / 行</th><th>修订 / 前序</th><th>值</th><th>记录人 / 时间</th><th>原因</th><th>状态</th></tr></thead><tbody><tr v-for="v in record.valueRevisions" :key="v.id"><td>{{definition(v.fieldCode)?.label??v.fieldCode}} {{v.occurrencePath}}</td><td>{{v.revisionNo}} / {{v.previousRevisionId??'—'}}</td><td>{{viewValue(v.normalizedValueJson)}}</td><td>{{v.recordedBy}} / {{v.recordedAt}}</td><td>{{v.changeReason}}</td><td>{{v.superseded?'已被后续修订替代':'当前'}}</td></tr></tbody></table></div></a-card>
<a-card title="复核与签名历史" class="form-section"><div v-for="review in record.reviews" :key="review.id" class="review-history"><strong>{{review.reviewType}} · {{review.decision}} · 修订 {{review.formRevision}}</strong><p>复核人 {{review.reviewerId}} · {{review.reviewedAt}} · 签名 {{review.signatureId}}</p><p>{{review.comment}} / {{review.reason}}</p><a-tag v-if="review.invalidatedAt" color="red">已失效：{{review.invalidationReason}}</a-tag></div><a-empty v-if="!record.reviews.length" description="尚无复核记录"/></a-card></details></template>
<a-modal :open="!!signatureMode" title="电子签名" :footer="null" :mask-closable="false" :closable="!busy" @cancel="signatureMode=null;password=''"><p>{{record?.formName}} · 内容修订 {{record?.formRevision}}</p><p class="digest">定义摘要 {{record?.definitionHash}}</p><p>签名人：{{auth.identity?.displayName}}（{{auth.identity?.loginName}}）</p><p v-if="selectedRule&&signatureMode==='REVIEW'">规则 {{selectedRule.reviewRuleId}} · {{selectedRule.reviewType}} · {{selectedRule.requiredRole}}</p><p v-else>签名含义：{{meaning}}</p><a-alert v-if="error" type="error" :message="error"/><form @submit.prevent="sign"><template v-if="signatureMode==='REVIEW'"><label class="form-inline-row"><span class="form-field-label">复核决定</span><select v-model="decision" class="master-native-input" :disabled="busy"><option value="PASS">通过</option><option value="REJECT">驳回</option></select></label><label class="form-inline-row"><span class="form-field-label">复核意见</span><textarea v-model="comment" class="master-native-input" maxlength="1000" :disabled="busy"/></label></template><label class="form-inline-row"><span class="form-field-label">操作原因</span><textarea v-model="reason" class="master-native-input" aria-label="签名原因" maxlength="1000" required :disabled="busy"/></label><label class="form-inline-row"><span class="form-field-label">再认证密码</span><input v-model="password" type="password" autocomplete="current-password" class="master-native-input" aria-label="再认证密码" required :disabled="busy"/></label><a-button type="primary" html-type="submit" :loading="busy" :disabled="conflict">确认电子签名</a-button></form></a-modal>
<a-modal :open="!!correction" title="受控更正" :footer="null" :mask-closable="false" :closable="!busy" @cancel="correction=null"><p>{{correctionField?.label}} {{correction?.occurrencePath}} · 当前字段修订 {{correction?.revisionNo}}</p><p>原值：{{correction?viewValue(correction.normalizedValueJson):''}}</p><a-alert v-if="error" type="error" :message="error"/><form @submit.prevent="correct"><label class="form-inline-row"><span class="form-field-label">更正后值</span><select v-if="correctionField?.fieldType==='BOOLEAN'" v-model="newValue" class="master-native-input"><option :value="null">未填写</option><option :value="true">是</option><option :value="false">否</option></select><select v-else-if="['ENUM','MULTI_ENUM'].includes(correctionField?.fieldType??'')" v-model="newValue" :multiple="correctionField?.fieldType==='MULTI_ENUM'" class="master-native-input"><option v-for="o in correctionField?.options.filter(x=>x.activeFlag)" :key="o.optionCode" :value="o.optionValue">{{o.optionLabel}}</option></select><input v-else :value="String(newValue??'')" class="master-native-input" maxlength="4000" @input="newValue=($event.target as HTMLInputElement).value||null"/></label><label class="form-inline-row"><span class="form-field-label">更正原因</span><textarea v-model="reason" class="master-native-input" aria-label="更正原因" maxlength="1000" required :disabled="busy"/></label><p>原值和签名证据保留。相关复核和签名将失效，记录需重新提交。</p><a-button type="primary" html-type="submit" :loading="busy" :disabled="conflict">保存受控更正</a-button></form></a-modal></main></template>
<style scoped>.runtime-evidence{padding:16px;border:1px solid var(--mes-ui-border);border-radius:8px;background:white;margin-top:16px}.runtime-evidence>summary{cursor:pointer;font-weight:600;font-size:14px}.runtime-provenance{width:100%;font-size:12px}.form-section{margin-top:16px}.runtime-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:20px 28px}.runtime-field{display:grid;grid-template-columns:120px minmax(0,1fr);align-items:start;gap:10px}.runtime-field label{padding-top:8px}.runtime-field label small{display:block;font-weight:400;overflow-wrap:anywhere}.runtime-control{display:flex;flex-wrap:wrap;gap:6px;align-items:center;min-width:0}.runtime-control>.master-native-input,.runtime-control>small{width:100%}.required{color:#cf1322}.digest{overflow-wrap:anywhere;min-width:0}.signature-row{display:flex;align-items:center;justify-content:space-between;gap:12px;padding:8px 0}.runtime-table{width:100%;border-collapse:collapse;min-width:620px}.runtime-table th,.runtime-table td{text-align:left;padding:10px;border-bottom:1px solid #e5e7eb;vertical-align:top;overflow-wrap:anywhere}.history-scroll{overflow-x:auto}.review-history{padding:12px 0;border-bottom:1px solid #e5e7eb}.barcode-source{display:flex;align-items:center;gap:6px;width:100%}.form-inline-row{grid-template-columns:110px minmax(0,1fr)}@media(max-width:900px){.runtime-grid{grid-template-columns:1fr}}@media(max-width:560px){.runtime-field{grid-template-columns:90px minmax(0,1fr);gap:8px}.form-inline-row{grid-template-columns:90px minmax(0,1fr)}.signature-row{align-items:flex-start}}</style>
